import{_ as n,o as t,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"Packer für Widget- und Tool-Pakete","description":"Pakete für HA Grafik Visual Studio prüfen und als .wg oder .tp erstellen.","frontmatter":{"title":"Packer für Widget- und Tool-Pakete","description":"Pakete für HA Grafik Visual Studio prüfen und als .wg oder .tp erstellen."},"headers":[],"relativePath":"projects/grafik-visual-studio/packer.md","filePath":"projects/grafik-visual-studio/packer.md","lastUpdated":1793023597000}'),a={name:"projects/grafik-visual-studio/packer.md"};function s(d,e,o,l,u,g){return t(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="packer-fur-widget-und-tool-pakete" tabindex="-1">Packer für Widget- und Tool-Pakete <a class="header-anchor" href="#packer-fur-widget-und-tool-pakete" aria-label="Permalink to &quot;Packer für Widget- und Tool-Pakete&quot;">​</a></h1><p>Pakete und Zusatztools werden zentral auf <a href="https://visualstudio.ugso-software.de/?lang=de" target="_blank" rel="noreferrer">visualstudio.ugso-software.de</a> angeboten. Diese Open-Source-Seite enthält Beschreibung und Anleitung; der Download erfolgt über den Paketkatalog.</p><p>Der Packer erstellt aus einem Quellordner ein Widget-Paket (<code>.wg</code>) oder Tool-Paket (<code>.tp</code>) für HA Grafik Visual Studio. Beide Dateien sind ZIP-Archive mit eigener Endung. Vor dem Export prüft der Packer das Manifest, die Paketstruktur, referenzierte SVG-/PNG-Bilder und die Grenzen der <a href="./widget-pakete">Widget-Paket-Schnittstelle</a> beziehungsweise <a href="./tool-pakete">Tool-Paket-Schnittstelle</a>. Paketdateien enthalten in der aktuellen Schnittstelle 0.1 keinen ausführbaren Code.</p><h2 id="paket-erstellen" tabindex="-1">Paket erstellen <a class="header-anchor" href="#paket-erstellen" aria-label="Permalink to &quot;Paket erstellen&quot;">​</a></h2><ol><li>Lege <code>manifest.json</code> im Wurzelverzeichnis eines Quellordners ab. Referenzierte Bilder gehören unter <code>icons/</code>. Die beiden Schnittstellenseiten zeigen die Felder und Beispiele.</li><li>Wähle im Packer <strong>Widget-Paket</strong> oder <strong>Tool-Paket</strong>, dann den Quellordner und einen vorhandenen Exportordner.</li><li>Prüfe die Ergebnisliste sowie Paket-ID, Version, Lizenz und Zielname. <strong>Exportieren</strong> wird erst bei gültigem Paket und freiem Zielnamen aktiv. Der Packer überschreibt keine vorhandene Datei.</li><li>Installiere die erzeugte <code>.wg</code>- oder <code>.tp</code>-Datei im Studio unter <strong>Einstellungen → Widget-Pakete</strong> oder <strong>Einstellungen → Tools</strong>. Die bisherigen Endungen <code>.wg.zip</code> und <code>.tp.zip</code> bleiben verwendbar.</li></ol><p>Der Packer prüft mit denselben Regeln wie der gebündelte Studio-Importer. Packer 0.3.0 unterstützt bis zu 64 Widgets pro Paket; ein Tool-Paket enthält in Schnittstelle 0.1 genau ein Tool. Das Studio prüft jedes importierte Paket zusätzlich selbst.</p><h2 id="github-und-direkte-registrierung" tabindex="-1">GitHub und direkte Registrierung <a class="header-anchor" href="#github-und-direkte-registrierung" aria-label="Permalink to &quot;GitHub und direkte Registrierung&quot;">​</a></h2><p>Ab Testversion <strong>0.3.1</strong> zeigt der Packer ein bereits gespeichertes Paket mit identischem Dateiinhalt grün als <strong>Datei gespeichert</strong> an, auch nach einem Neustart. Ein erneuter Export bleibt deaktiviert. Bei abweichendem Inhalt schützt die Prüfung weiterhin vor dem Überschreiben. Der breite Button <strong>GitHub &amp; Katalog …</strong> befindet sich direkt unter der Prüfliste.</p><p>Seit <strong>Packer 0.3.0</strong> öffnet <strong>GitHub &amp; Katalog …</strong> ein exportiertes <code>.wg</code>- oder <code>.tp</code>-Paket zur Prüfung und Veröffentlichung. Die unten angebotene Testversion <strong>0.3.1</strong> enthält diese Erweiterung und die korrigierte Anzeige gespeicherter Dateien.</p><ol><li>Installiere die <a href="https://cli.github.com/" target="_blank" rel="noreferrer">GitHub CLI</a> und melde dich im Terminal mit <code>gh auth login</code> an. Trage dein öffentliches Repository ein und wähle <strong>Releases laden</strong>.</li><li>Wähle den Release-Tag und bestätige <strong>Paket auf GitHub veröffentlichen</strong>. Für einen neuen Release aktiviere <strong>Release für vorhandenen Git-Tag erstellen</strong>; der Tag muss bereits auf GitHub vorhanden sein. Vorhandene Dateien werden nicht überschrieben.</li><li>Der Download-Link wird übernommen. Alternativ kannst du einen bereits veröffentlichten HTTPS-Link zur festen <code>.wg</code>- oder <code>.tp</code>-Version direkt eingeben und den GitHub-Schritt überspringen.</li><li>Ergänze Lizenzlink, Beschreibung, interne Kontaktadresse und benötigte Studio-Mindestversion. Neue Funktionen werden mit <strong>Nein / Ja / Unsicher</strong> angegeben. Bei Ja oder Unsicher ist eine Beschreibung erforderlich; die Mindestversion darf noch unbekannt sein.</li><li>Lies die <a href="https://visualstudio.ugso-software.de/privacy" target="_blank" rel="noreferrer">Registrierungshinweise</a>, bestätige Verarbeitung und Verteilungsrechte und wähle <strong>Im Katalog registrieren</strong>. Vor dem Senden zeigt der Packer Empfänger und Angaben an. Das Originalpaket wird zur automatischen Analyse mitgeschickt.</li><li>Kopiere den privaten Verwaltungslink nach erfolgreicher Einreichung. Das Paket erscheint nach manueller Prüfung und Freigabe im Katalog. Bei unklarer Netzwerkantwort zuerst prüfen, ob die Version gespeichert wurde; der Packer wiederholt die Einreichung nicht automatisch.</li></ol><p>Die Kontaktadresse geht intern an den Katalog und gegebenenfalls sein Prüfpostfach. Name, E-Mail und Webseite werden nicht öffentlich angezeigt. Der Packer speichert nur Repository und Lizenzlink als Komforteinstellung, keine Kontaktadresse, GitHub-Tokens, Einwilligungen oder Verwaltungslinks. Netzwerkaktionen laufen im Hintergrund. Widget-Quellordner können zusätzlich <code>LICENSE.txt</code> und <code>README.md</code> enthalten.</p><h2 id="programm-und-dateiendungen" tabindex="-1">Programm und Dateiendungen <a class="header-anchor" href="#programm-und-dateiendungen" aria-label="Permalink to &quot;Programm und Dateiendungen&quot;">​</a></h2><p>Die Qt-Oberfläche läuft unter Windows und Linux. Der Button <strong>Endungen registrieren</strong> zeigt zuerst eine Vorschau und richtet nach Bestätigung eigene Icons und „Öffnen mit“-Einträge für <code>.wg</code> und <code>.tp</code> beim aktuellen Benutzer ein. Eine bestehende Standard-App wird nicht geändert. Der Packer kann ein vorhandenes Paket zur Prüfung öffnen, ohne es zu installieren. Nach dem Verschieben des Programms muss die Dateityp-Registrierung erneut ausgeführt werden.</p><p>Version <strong>0.3.1</strong> ist als signierter Test-Release für Windows und Linux im <a href="https://visualstudio.ugso-software.de/?kind=helper&amp;lang=de" target="_blank" rel="noreferrer">Paketkatalog</a> erhältlich:</p><table tabindex="0"><thead><tr><th>System</th><th>Download</th><th>SHA-256</th></tr></thead><tbody><tr><td>Windows x86_64</td><td><a href="https://visualstudio.ugso-software.de/downloads/helpertools/HA-Grafik-Packer-0.3.1-windows-x86_64.zip" target="_blank" rel="noreferrer">ZIP herunterladen</a></td><td><code>7047e6ee5bb2327cf80432d2c37e0f82516284c22c0d4910ff3d4d64950efd8a</code></td></tr><tr><td>Linux x86_64</td><td><a href="https://visualstudio.ugso-software.de/downloads/helpertools/HA-Grafik-Packer-0.3.1-linux-x86_64.tar.gz" target="_blank" rel="noreferrer">TAR.GZ herunterladen</a></td><td><code>e094331c7281957764dee38a8a117d932a2589581117daf68f1e146b71fd9a19</code></td></tr></tbody></table><p>Entpacke das Archiv vollständig und starte <code>HA-Grafik-Packer.exe</code> beziehungsweise <code>HA-Grafik-Packer</code>. Der Ordner <code>_internal</code> muss daneben bleiben; er enthält auch die separat austauschbaren Qt-Bibliotheken. Beide Plattform-Builds wurden mit Tests und einem Selbsttest nach dem Entpacken geprüft. Linux benötigt Qt-Systembibliotheken für EGL/OpenGL. Lizenztexte und Hinweise liegen im Archiv.</p><h2 id="download-prufen" tabindex="-1">Download prüfen <a class="header-anchor" href="#download-prufen" aria-label="Permalink to &quot;Download prüfen&quot;">​</a></h2><p>Lade für Version 0.3.1 <a href="https://visualstudio.ugso-software.de/downloads/helpertools/SHA256SUMS-0.3.1" target="_blank" rel="noreferrer">SHA256SUMS-0.3.1</a> und <a href="https://visualstudio.ugso-software.de/downloads/helpertools/SHA256SUMS-0.3.1.sig" target="_blank" rel="noreferrer">SHA256SUMS-0.3.1.sig</a> herunter. Die <a href="https://raw.githubusercontent.com/rockbaer2007/ugso-opensource-docs/main/docs/public/keys/packer-allowed-signers" target="_blank" rel="noreferrer">Vertrauensdatei für OpenSSH</a> und der <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/packer-release.pub" target="_blank" rel="noreferrer">öffentliche Release-Schlüssel</a> werden getrennt vom Release bereitgestellt. Der Ed25519-Fingerabdruck ist <code>SHA256:W3iUvKedcI4FWS1kMoBrLlrAF2GbsB4sELphG0uITLE</code>. Die früheren Prüfsummendateien ohne Versionsnummer gehören zu 0.2.0.</p><p>Prüfe zuerst die Signatur. Unter Linux im Downloadordner:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packer-allowed-signers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packer-release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ha-grafik-visual-studio-packer-release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS-0.3.1.sig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS-0.3.1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS-0.3.1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Unter Windows funktionieren dieselben Signaturparameter in <code>cmd.exe</code> mit der gezeigten Eingabeumleitung. Vergleiche danach <code>certutil -hashfile DATEINAME SHA256</code> mit dem Wert in <code>SHA256SUMS-0.3.1</code>. Lade Schlüssel und Vertrauensdatei vor dem Prüfen von den oben verlinkten Quellen. Der Packer-Quellcode bleibt im privaten Entwicklungs-Repository.</p>`,21)])])}const k=n(a,[["render",s]]);export{c as __pageData,k as default};
